"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

PAGE_SIZE = 100
MAX_CURSOR_RESTARTS = 5

QUERY = """
query Settlements($after: String) {
  settlements(first: 100, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}
"""


def post_graphql(url, query, variables):
    body = json.dumps({"query": query, "variables": variables}).encode()
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
    while True:
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            # Under load the API asks us to wait, then retry the identical request.
            try:
                delay = float(exc.headers.get("Retry-After", "1"))
            except (TypeError, ValueError):
                delay = 1.0
            time.sleep(max(delay, 0))
            # Recreate the request from the same body for the retry.
            req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})


def fetch_page(url, after):
    variables = {"after": after}
    result = post_graphql(url, QUERY, variables)
    if result.get("errors"):
        raise GraphQLError(result["errors"])
    return result["data"]["settlements"]


class GraphQLError(Exception):
    pass


def fetch_all(url):
    """Traverse every page, keeping the last version received for each settlement id."""
    settlements = {}
    after = None
    restarts = 0
    while True:
        try:
            page = fetch_page(url, after)
        except GraphQLError:
            if after is None or restarts >= MAX_CURSOR_RESTARTS:
                raise
            # Malformed or expired cursor: start again without `after`.
            # Deduplication below keeps this from emitting a settlement twice.
            restarts += 1
            after = None
            continue

        for settlement in page["nodes"]:
            # Amended settlements are delivered again later; the last copy wins.
            settlements[settlement["id"]] = settlement

        page_info = page["pageInfo"]
        # Short or empty pages are normal; only hasNextPage marks the end.
        if not page_info["hasNextPage"]:
            break
        after = page_info["endCursor"]

    return list(settlements.values())


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    settlements = fetch_all(f"{args.base_url.rstrip('/')}/v2/graphql")
    with open(args.out, "w") as f:
        for s in settlements:
            f.write(json.dumps(s) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

